SELECT name,type,comment FROM system.columns WHERE database='system' AND table='query_log' AND name IN ('query_id','event_time_microseconds','query_start_time_microseconds','query_duration_ms','read_rows','read_bytes','result_rows','result_bytes','ProfileEvents','Settings','memory_usage','peak_threads_usage','query_cache_usage','is_initial_query','query_kind','normalized_query_hash','hostname','exception_code') ORDER BY position LIMIT 30 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames